def survivors(ids, seen=None):
 seen=set() if seen is None else seen
 out=[]
 for k in ids:
  if k in seen: raise ValueError('coverage cycle '+k)
  arr=survivors(D[k][0],seen|{k}) if k in D else [k]
  for v in arr:
   if v not in out:out.append(v)
 return out
D={k:(survivors(v[0]),v[1]) for k,v in D.items()}

