  records.append({'id':k,'question_verbatim':qs[k]['question'],'decision':'keep_standalone_question','challenge_status':'whole_bank_consistency_sweep','distinct_surviving_procedure':reason,'source_references':ans[k]['source_references'],'earlier_requested_parts':evidence([x for x in qs if x in __import__('re').findall(r'Q[0-9]+',reason) and int(x[1:])<int(k[1:])])})
